// [🧰repo⌨️cli💻maingo🔖cliadapter✂️config](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/d/i/Config)
type Config struct {
	Format  string
	Verbose bool
	Repo    string
	Timeout time.Duration
}

// IsJSON MUST return true only when the condition is met.
// IsJSON reports whether the Config is j s o n.
// [🧰repo⌨️cli💻maingo🔖cliadapter🛠️isjson](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/d/i/IsJSON)
func (c *Config) IsJSON() bool {
	return c.Format == "json"
}

// IsMarkdown MUST return true only when the condition is met.
// IsMarkdown reports whether the Config is markdown.
// [🧰repo⌨️cli💻maingo🔖cliadapter🛠️ismarkdown](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/d/i/IsMarkdown)
func (c *Config) IsMarkdown() bool {
	return c.Format == "md"
}

// IsText MUST return true only when the condition is met.
// IsText reports whether the Config is text.
// [🧰repo⌨️cli💻maingo🔖cliadapter🛠️istext](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/d/i/IsText)
func (c *Config) IsText() bool {
