// GenerateTechnologyTodos holds the data fields for a GenerateTechnologyTodos record.
// GenerateTechnologyTodos MUST perform the GenerateTechnologyTodos operation.
func GenerateTechnologyTodos(technologyName string) error {
	technology := findTechnologyByName(technologyName)
	if technology == nil {
		return fmt.Errorf("technology %q not found", technologyName)
	}
	var entries []EntityEntry
	for _, bundle := range technology.Bundles {
		bundleRoot := filepath.Join(rootDir, bundle.Root)
		todos, _ := ScanTodos(bundleRoot)
		for _, todo := range todos {
			if todo.Location != nil && isGitIgnored(todo.Location.FilePath) {
				continue
			}
			if todo.Location != nil && IsGenerated(todo.Location.FilePath) {
				continue
			}
			title := todo.Name
			desc := todo.Description
			parentPath := todo.ParentID
			relParent, _ := filepath.Rel(rootDir, parentPath)
			relParent = NormalizePath(relParent)
			entityID := relParent
			entityURI := buildFileUriFromPath(relParent)
			if todo.Location != nil {
				relLoc, _ := filepath.Rel(rootDir, todo.Location.FilePath)
				relLoc = NormalizePath(relLoc)
				entityID = relLoc
				entityURI = buildFileUriFromPath(relLoc)
			}
			text := "### TODO: " + title
			if desc != "" {
				text += "\n" + desc
			}
			entries = append(entries, EntityEntry{ID: entityID, URI: entityURI, Text: text})
		}
	}
	var sb strings.Builder
	sb.WriteString("# \U0001F533 TODOs\n")
	for _, e := range entries {
		sb.WriteString("\n## [" + e.ID + "](" + e.URI + ")\n\n")
		sb.WriteString(e.Text + "\n")
	}
	outputPath := filepath.Join(rootDir, technology.Root, "TODOS.md")
	return WriteTextFile(outputPath, sb.String())
}

func findFolderReadmes(bundleRoot string) []string {
	var readmes []string
	absRoot := filepath.Join(rootDir, bundleRoot)
	filepath.WalkDir(absRoot, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() {
			name := d.Name()
			if strings.HasPrefix(name, ".") || name == "node_modules" || name == "dist" || name == "build" || name == "target" || name == "__pycache__" {
				return fs.SkipDir
			}
			return nil
		}
		if d.Name() == "README.md" {
			relPath, _ := filepath.Rel(rootDir, path)
			relPath = NormalizePath(relPath)
			if relPath != NormalizePath(filepath.Join(bundleRoot, "README.md")) {
				readmes = append(readmes, relPath)
			}
		}
		return nil
	})
	return readmes
}

func bundleCommand(factory EngineFactory, config *Config) *cobra.Command {
	root := &cobra.Command{Use: "bundle", Short: "Bundle management commands"}
	listCmd := &cobra.Command{
		Use:   "list",
		Short: "List bundles",
		RunE: func(cmd *cobra.Command, args []string) error {
			opts := getStreamOptions(cmd)
			statusFilter := getStatusFilter(cmd)
			var bundlesWithOpenTickets map[string]bool
			if statusFilter != nil {
				bundlesWithOpenTickets = getBundlesWithOpenTickets()
			}

			stream := make(chan Event)
			go func() {
				defer close(stream)
				stream <- Event{Kind: KindStart, Command: "bundle list"}

				bundleChan := make(chan Bundle)
				go func() {
					StreamBundles(context.Background(), bundleChan, opts)
				}()

				for b := range bundleChan {

					if statusFilter != nil {
						hasOpenTicket := bundlesWithOpenTickets[b.Name]
						if *statusFilter == "open" && !hasOpenTicket {
							continue
						}
						if *statusFilter == "closed" && hasOpenTicket {
							continue
						}
					}

					data, err := json.Marshal(map[string]interface{}{"bundle": b})
					if err != nil {
						continue
					}
					stream <- Event{Kind: KindResult, Command: "bundle list", Data: data}
				}
				stream <- Event{Kind: KindDone, Done: &DonePayload{ExitCode: 0, Status: "ok"}}
			}()

			return renderStream(cmd, config, stream)
		},
	}
	bindStreamFlags(listCmd)
	bindStatusFlags(listCmd)

	treeCmd := &cobra.Command{
		Use:   "tree",
		Short: "Show bundle tree",
		RunE: func(cmd *cobra.Command, args []string) error {
			opts := getStreamOptions(cmd)
			statusFilter := getStatusFilter(cmd)
			var bundlesWithOpenTickets map[string]bool
			if statusFilter != nil {
				bundlesWithOpenTickets = getBundlesWithOpenTickets()
			}
			_ = bundlesWithOpenTickets

			stream := make(chan Event)
			go func() {
				defer close(stream)
				stream <- Event{Kind: KindStart, Command: "bundle tree"}

				bundleChan := make(chan Bundle)
				go func() {
					StreamBundles(context.Background(), bundleChan, opts)
				}()

				var bundles []Bundle
				for b := range bundleChan {
					bundles = append(bundles, b)
				}

				sort.Slice(bundles, func(i, j int) bool {
					return bundles[i].Name < bundles[j].Name
				})

				if config.IsMarkdown() {
					var sb strings.Builder
					for _, b := range bundles {
						bMap := map[string]interface{}{}
						bBytes, _ := json.Marshal(b)
						json.Unmarshal(bBytes, &bMap)
						line := renderEntityMarkdown("bundle", bMap)
						sb.WriteString(line + "\n")
					}
					data, _ := json.Marshal(map[string]string{"markdown": sb.String()})
					stream <- Event{Kind: KindResult, Command: "bundle tree", Data: data}
				} else {
					stream <- Event{Kind: KindLog, Level: "info", Command: "bundle tree", Message: "."}
					for i, b := range bundles {
						connector := "├── "
						if i == len(bundles)-1 {
							connector = "└── "
						}
						stream <- Event{Kind: KindLog, Level: "info", Command: "bundle tree", Message: connector + b.Name}
					}
				}
				stream <- Event{Kind: KindDone, Done: &DonePayload{ExitCode: 0, Status: "ok"}}
			}()
			return renderStream(cmd, config, stream)
		},
	}
	bindStreamFlags(treeCmd)
	bindStatusFlags(treeCmd)

	root.AddCommand(listCmd)
	root.AddCommand(treeCmd)
	return root
}

