func levenshtein(a, b string) int {
	la, lb := len(a), len(b)
	if la == 0 {
		return lb
	}
	if lb == 0 {
		return la
	}
	prev := make([]int, lb+1)
	curr := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		curr[0] = i
		for j := 1; j <= lb; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			ins := curr[j-1] + 1
			del := prev[j] + 1
			sub := prev[j-1] + cost
			m := ins
			if del < m {
				m = del
			}
			if sub < m {
				m = sub
			}
			curr[j] = m
		}
		prev, curr = curr, prev
	}
	return prev[lb]
}

func fuzzyContains(text, term string) bool {
	if strings.Contains(text, term) {
		return true
	}
	maxDist := 1
	if len(term) > 5 {
		maxDist = 2
	}
	words := strings.Fields(text)
	for _, w := range words {
		if levenshtein(w, term) <= maxDist {
			return true
		}
		if len(w) >= len(term) {
			for i := 0; i <= len(w)-len(term)+maxDist && i <= len(w)-1; i++ {
				end := i + len(term) + maxDist
				if end > len(w) {
					end = len(w)
				}
				sub := w[i:end]
				if levenshtein(sub, term) <= maxDist {
					return true
				}
			}
		}
	}
	return false
}
func searchTreeInMemory(root *TreeNode, query string) *TreeNode {
	terms := strings.Fields(strings.ToLower(query))
	if len(terms) == 0 {
		return root
	}
	matchedIDs := make(map[string]bool)
	var walk func(node *TreeNode)
	walk = func(node *TreeNode) {
		if node.Kind != TreeNodeCategory {
			docID := node.ID
			if docID == "" {
				docID = node.Label
			}
			text := strings.ToLower(strings.Join([]string{
				node.Label,
				node.ID,
				node.SubKind,
				node.Description,
				node.URI,
				node.Status,
				node.Contributor,
				string(node.Kind),
			}, " "))
			allMatch := true
			for _, term := range terms {
				if !fuzzyContains(text, term) {
					allMatch = false
					break
				}
			}
			if allMatch {
				matchedIDs[docID] = true
			}
		}
		for _, c := range node.Children {
			walk(c)
		}
	}
	walk(root)
	if len(matchedIDs) == 0 {
		return &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}
	}
	pruned := pruneUnmatched(root, matchedIDs)
	if pruned == nil {
		return &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}
	}
	return pruned
}

func pruneUnmatched(node *TreeNode, matchedIDs map[string]bool) *TreeNode {
	return pruneUnmatchedInner(node, matchedIDs, false)
}

func pruneUnmatchedInner(node *TreeNode, matchedIDs map[string]bool, ancestorMatched bool) *TreeNode {
	docID := node.ID
	if docID == "" {
		docID = node.Label
	}
	selfMatched := matchedIDs[docID]
	keepDescendants := ancestorMatched || selfMatched
	var kept []*TreeNode
	for _, c := range node.Children {
		fc := pruneUnmatchedInner(c, matchedIDs, keepDescendants)
		if fc != nil {
			kept = append(kept, fc)
		}
	}
	if keepDescendants || len(kept) > 0 || node.Kind == TreeNodeCategory {
		if node.Kind == TreeNodeCategory && len(kept) == 0 && !selfMatched && !ancestorMatched {
			return nil
		}
		copy := *node
		copy.Children = kept
		return &copy
	}
	return nil
}

