func treeNodeKindToEntityKind(k TreeNodeKind) string {
	switch k {
	case TreeNodeTechnology:
		return "technology"
	case TreeNodeBundle:
		return "bundle"
	case TreeNodeFolder:
		return "folder"
	case TreeNodeFile:
		return "file"
	case TreeNodeSection:
		return "section"
	case TreeNodeDefinition:
		return "definition"
	case TreeNodeGoal:
		return "goal"
	case TreeNodeTicket:
		return "ticket"
	case TreeNodeDraft:
		return "draft"
	case TreeNodeTodo:
		return "todo"
	case TreeNodePolicy:
		return "policy"
