// Gzip-compressed JSON cache of the full TreeNode tree under .repo/cache. Uses same git fingerprint as Query Cache for invalidation. Saves ~95% of tree build time on cache hit.

func getTreeCachePath() string {
	return filepath.Join(getCacheDir(), "tree.json.gz")
}

func getTreeCacheMetaPath() string {
	return filepath.Join(getCacheDir(), "tree-meta.json")
}

func saveTreeCache(tree *TreeNode, meta *cacheMeta) error {
	dir := getCacheDir()
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := json.Marshal(tree)
	if err != nil {
		return err
	}
	var buf bytes.Buffer
	gz, err := gzip.NewWriterLevel(&buf, gzip.BestSpeed)
	if err != nil {
		return err
	}
	if _, err := gz.Write(data); err != nil {
		gz.Close()
		return err
	}
	if err := gz.Close(); err != nil {
		return err
	}
	if err := os.WriteFile(getTreeCachePath(), buf.Bytes(), 0644); err != nil {
		return err
	}
	metaData, err := json.MarshalIndent(meta, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(getTreeCacheMetaPath(), metaData, 0644)
}

func loadTreeCache() (*TreeNode, *cacheMeta, error) {
	metaData, err := os.ReadFile(getTreeCacheMetaPath())
	if err != nil {
		return nil, nil, err
	}
	var meta cacheMeta
	if err := json.Unmarshal(metaData, &meta); err != nil {
		return nil, nil, err
	}
	if meta.SchemaVersion != cacheSchemaVersion {
		return nil, nil, fmt.Errorf("schema version mismatch")
	}
	compressed, err := os.ReadFile(getTreeCachePath())
	if err != nil {
		return nil, nil, err
	}
	gz, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		return nil, nil, err
	}
	defer gz.Close()
	data, err := io.ReadAll(gz)
	if err != nil {
		return nil, nil, err
	}
	var tree TreeNode
	if err := json.Unmarshal(data, &tree); err != nil {
		return nil, nil, err
	}
	return &tree, &meta, nil
}

// [🧰repo⌨️cli💻maingo🔖cliadapter🔖treelogic🔖treecache🛠️buildmonorepotreecached](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Tree%20Logic/s/Tree%20Cache/d/i/BuildMonorepoTreeCached)
// BuildMonorepoTreeCached holds the data fields for a BuildMonorepoTreeCached record.
// BuildMonorepoTreeCached MUST perform the BuildMonorepoTreeCached operation.
func BuildMonorepoTreeCached(ctx context.Context, opts ...TreeBuildOptions) *TreeNode {
	repoRoot := GetRootDir()
	fp, newMeta := computeCompositeFingerprint(repoRoot)
	cached, cachedMeta, err := loadTreeCache()
	if err == nil && cachedMeta.Fingerprint == fp {
		return cached
	}
	tree := BuildMonorepoTree(ctx, TreeBuildOptions{IncludeSections: true})
	saveTreeCache(tree, newMeta)
	return tree
}

