		Use:   "loc-by-language",
		Short: "LOC treemap grouped by programming language",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			fmt.Fprint(cmd.OutOrStdout(), MermaidLocByLanguage())
			return nil
		},
	})
	return root
}

