// ResolveAllowedLLM MUST return an error for unrecognized values.
// ResolveAllowedLLM resolves and validates the allowed l l m against known values.
// [🧰repo⌨️cli💻maingo🔖graphqltypes🛠️resolveallowedllm](repo://p/i/repo/b/b/cli/f/main.go/s/GraphQL%20Types/d/i/ResolveAllowedLLM)
func ResolveAllowedLLM(llm string) (string, error) {
	llmSlug := NormalizeLLMSlug(llm)
	bestMatch := ""
	for _, allowed := range AllowedLLMs {
		if strings.Contains(llmSlug, NormalizeLLMSlug(allowed)) {
			if len(allowed) > len(bestMatch) {
				bestMatch = allowed
			}
		}
	}
	if bestMatch == "" {
		return "", fmt.Errorf("llm '%s' is not allowed. Please use one of: %s", llmSlug, strings.Join(AllowedLLMs, ", "))
	}
	return bestMatch, nil
}

