// ListDrafts MUST return a consistent snapshot of available entries.
// ListDrafts returns all available drafts entries.
// [🧰repo⌨️cli💻maingo🔖graphqltypes🔖drafts🛠️listdrafts](repo://p/i/repo/b/b/cli/f/main.go/s/GraphQL%20Types/s/Drafts/d/i/ListDrafts)
func ListDrafts() ([]*Draft, error) {
	draftsDir := GetDraftsPath()
	if !IsDir(draftsDir) {
		return []*Draft{}, nil
	}
	entries, err := os.ReadDir(draftsDir)
	if err != nil {
		return nil, err
	}
	var drafts []*Draft
	for _, entry := range entries {
		if entry.IsDir() {
			drafts = append(drafts, &Draft{ID: entry.Name()})
		}
	}
	return drafts, nil
}

// CreateDraft MUST persist the new entity and return a reference to it.
// CreateDraft creates a new draft and persists it.
// [🧰repo⌨️cli💻maingo🔖graphqltypes🔖drafts🛠️createdraft](repo://p/i/repo/b/b/cli/f/main.go/s/GraphQL%20Types/s/Drafts/d/i/CreateDraft)
func CreateDraft(title string, files []string) (*Draft, error) {
	id := Slugify(title)
	if id == "" {
		return nil, fmt.Errorf("invalid draft title")
	}
	draftPath := filepath.Join(GetDraftsPath(), id)
	if IsDir(draftPath) {
		return nil, fmt.Errorf("draft already exists: %s", id)
	}
	if err := EnsureDir(draftPath); err != nil {
		return nil, err
	}
	for _, f := range files {
		src := f
		dst := filepath.Join(draftPath, filepath.Base(f))

		if err := CopyFile(src, dst); err != nil {

			os.RemoveAll(draftPath)
			return nil, fmt.Errorf("failed to copy file %s: %w", src, err)
		}
	}
	return &Draft{ID: id}, nil
}

// DeleteDraft MUST remove all associated data for the entity.
// DeleteDraft removes the specified draft.
// [🧰repo⌨️cli💻maingo🔖graphqltypes🔖drafts🛠️deletedraft](repo://p/i/repo/b/b/cli/f/main.go/s/GraphQL%20Types/s/Drafts/d/i/DeleteDraft)
func DeleteDraft(id string) error {
	draftPath := filepath.Join(GetDraftsPath(), id)
	if !IsDir(draftPath) {
		return nil
	}
	return os.RemoveAll(draftPath)
}

