// ToStreamOptions MUST map all filter input fields to stream options.
// ToStreamOptions converts the filter input into stream options.
// [🧰repo⌨️cli💻maingo🔖graphqltypes🔖graphqlinputtypes🛠️tostreamoptions](repo://p/i/repo/b/b/cli/f/main.go/s/GraphQL%20Types/s/GraphQL%20Input%20Types/d/i/ToStreamOptions)
func (f *FilterInput) ToStreamOptions() StreamOptions {
	if f == nil {
		return StreamOptions{}
	}
	opts := StreamOptions{}
	if f.Filter != nil {
		opts.Filter = *f.Filter
	}
	if f.Regex != nil {
		opts.Regex = *f.Regex
	}
	if f.MatchCase != nil {
		opts.MatchCase = *f.MatchCase
	}
	if f.MatchWholeWord != nil {
		opts.MatchWholeWord = *f.MatchWholeWord
	}
	if f.ShowIgnored != nil {
		opts.ShowIgnored = *f.ShowIgnored
	}
	if f.ShowGenerated != nil {
		opts.ShowGenerated = *f.ShowGenerated
	}
	opts.ExcludeKinds = f.ExcludeKinds
	opts.IncludeKinds = f.IncludeKinds
	return opts
}

