// GetIssueDetails MUST perform the GetIssueDetails operation.
// GetIssueDetails holds the data fields for a GetIssueDetails record.
// [🧰repo⌨️cli💻maingo🔖providers🔖githubmanagementprovider🛠️getissuedetails](repo://p/i/repo/b/b/cli/f/main.go/s/Providers/s/GitHub%20Management%20Provider/d/i/GetIssueDetails)
func (p *GitHubManagementProvider) GetIssueDetails(issueURL string) (*ManagementIssue, error) {
	issue, err := ghGetIssueDetails(issueURL)
	if err != nil {
		return nil, err
	}
	mi := &ManagementIssue{URL: issue.URL, State: issue.State, Title: issue.Title, Body: issue.Body}
	if issue.Milestone != nil {
		mi.Milestone = &struct {
			Number int    `json:"number"`
			Title  string `json:"title"`
		}{Number: issue.Milestone.Number, Title: issue.Milestone.Title}
	}
	for _, l := range issue.Labels {
		mi.Labels = append(mi.Labels, struct {
			Name string `json:"name"`
		}{Name: l.Name})
	}
	return mi, nil
}

