// [🧰repo⌨️cli💻maingo🔖providers🔖githubmanagementprovider🛠️listissuesforlabelsync](repo://p/i/repo/b/b/cli/f/main.go/s/Providers/s/GitHub%20Management%20Provider/d/i/ListIssuesForLabelSync)
// ListIssuesForLabelSync holds the data fields for a ListIssuesForLabelSync record.
// ListIssuesForLabelSync MUST perform the ListIssuesForLabelSync operation.
func (p *GitHubManagementProvider) ListIssuesForLabelSync() ([]ManagementIssue, error) {
	issues, err := ghListIssuesForLabelSync()
	if err != nil {
		return nil, err
	}
	result := make([]ManagementIssue, len(issues))
	for i, issue := range issues {
		result[i] = ManagementIssue{URL: issue.URL, State: issue.State, Title: issue.Title, Body: issue.Body}
		for _, l := range issue.Labels {
			result[i].Labels = append(result[i].Labels, struct {
				Name string `json:"name"`
			}{Name: l.Name})
		}
	}
	return result, nil
}

