// ExtraOrphanDefinitions MUST operate on the GoLanguage receiver and return consistent results.
// ExtraOrphanDefinitions performs the extra orphan definitions operation on the GoLanguage.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🔖typescript🔖go🛠️extraorphandefinitions](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/s/TypeScript/s/Go/d/i/ExtraOrphanDefinitions)
func (l *GoLanguage) ExtraOrphanDefinitions(lines []string) []DefinitionRange {
	var defs []DefinitionRange
	for i := 0; i < len(lines); i++ {
		trimmed := strings.TrimSpace(lines[i])
		if strings.HasPrefix(trimmed, "package ") {
			name := fmt.Sprintf("package-%d", i+1)
			defs = append(defs, DefinitionRange{Name: name, Start: i + 1, End: i + 1, Excerpt: trimmed})
			break
		}
	}
	for i := 0; i < len(lines); i++ {
		trimmed := strings.TrimSpace(lines[i])
		if strings.HasPrefix(trimmed, "import ") {
			start := i + 1
			end := start
			if strings.HasPrefix(trimmed, "import (") {
				for j := i + 1; j < len(lines); j++ {
					if strings.TrimSpace(lines[j]) == ")" {
						end = j + 1
						i = j
						break
					}
				}
			}
			name := fmt.Sprintf("import-%d", start)
			defs = append(defs, DefinitionRange{Name: name, Start: start, End: end, Excerpt: strings.TrimSpace(lines[start-1])})
		}
	}
	return defs
}

// ExtractImports MUST return the extracted value without side effects.
// ExtractImports extracts the imports from the given input.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🔖typescript🔖go🛠️extractimports](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/s/TypeScript/s/Go/d/i/ExtractImports)
func (l *GoLanguage) ExtractImports(content string) ([]string, string) {
	lines := strings.Split(content, "\n")
	var imports []string
	var bodyLines []string
	inImportBlock := false
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)

		if inImportBlock {
			if trimmed == ")" {
				inImportBlock = false
			} else if trimmed != "" {

				imports = append(imports, strings.Trim(trimmed, ","))
			}
			continue
		}

		if strings.HasPrefix(trimmed, "import (") {
			inImportBlock = true
			continue
		}

		if strings.HasPrefix(trimmed, "import ") {

			imports = append(imports, strings.TrimPrefix(trimmed, "import "))
			continue
		}

		bodyLines = append(bodyLines, line)
	}
	return imports, strings.Join(bodyLines, "\n")
}

// FormatImports MUST produce a well-formed imports string.
// FormatImports formats the imports into its string representation.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🔖typescript🔖go🛠️formatimports](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/s/TypeScript/s/Go/d/i/FormatImports)
func (l *GoLanguage) FormatImports(imports []string) string {
	if len(imports) == 0 {
		return ""
	}
	importBlock := "import (\n"
	seen := make(map[string]bool)
	var uniqueImports []string
	for _, imp := range imports {
		if !seen[imp] {
			seen[imp] = true
			uniqueImports = append(uniqueImports, imp)
		}
	}
	sort.Strings(uniqueImports)
	for _, imp := range uniqueImports {
		importBlock += "\t" + imp + "\n"
	}
	importBlock += ")"
	return importBlock
}

// ExtractPackage MUST return the extracted value without side effects.
// ExtractPackage extracts the package from the given input.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🔖typescript🔖go🛠️extractpackage](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/s/TypeScript/s/Go/d/i/ExtractPackage)
func (l *GoLanguage) ExtractPackage(content string) (string, string) {
	lines := strings.Split(content, "\n")
	pkg := ""
	var bodyLines []string
	foundPkg := false
	for _, line := range lines {
		if !foundPkg && strings.HasPrefix(strings.TrimSpace(line), "package ") {
			pkg = line
			foundPkg = true
			continue
		}
		bodyLines = append(bodyLines, line)
	}
	return pkg, strings.Join(bodyLines, "\n")
}

