// ExtractImports MUST return the extracted value without side effects.
// ExtractImports extracts the imports from the given input.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🔖typescript🔖c🛠️extractimports](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/s/TypeScript/s/C/s//d/i/ExtractImports)
func (l *CSharpLanguage) ExtractImports(content string) ([]string, string) {
	lines := strings.Split(content, "\n")
	var imports []string
	var bodyLines []string
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "using ") && strings.HasSuffix(trimmed, ";") {
			imports = append(imports, line)
		} else {
			bodyLines = append(bodyLines, line)
		}
	}
	return imports, strings.Join(bodyLines, "\n")
}

// FormatImports MUST produce a well-formed imports string.
// FormatImports formats the imports into its string representation.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🔖typescript🔖c🛠️formatimports](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/s/TypeScript/s/C/s//d/i/FormatImports)
func (l *CSharpLanguage) FormatImports(imports []string) string {
	if len(imports) == 0 {
		return ""
	}
	seen := make(map[string]bool)
	var uniqueImports []string
	for _, imp := range imports {
		if !seen[imp] {
			seen[imp] = true
			uniqueImports = append(uniqueImports, imp)
		}
	}
	sort.Strings(uniqueImports)
	return strings.Join(uniqueImports, "\n")
}

