// [🧰repo⌨️cli💻maingo🔖types🔖languages✂️gitauthor](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/d/i/GitAuthor)
type GitAuthor struct {
	Name   string `json:"name,omitempty" yaml:"name,omitempty"`
	Email  string `json:"email,omitempty" yaml:"email,omitempty"`
	GitHub string `json:"github,omitempty" yaml:"github,omitempty"`
}

// String MUST return the canonical string value.
// String returns the string representation of the GitAuthor.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🛠️string](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/d/i/String)
func (a GitAuthor) String() string {
	if a.Email != "" {
		return fmt.Sprintf("%s <%s>", a.Name, a.Email)
	}
	return a.Name
}

func parseGitAuthor(s string) GitAuthor {
	res := GitAuthor{}
	if strings.Contains(s, " <") {
		parts := strings.Split(s, " <")
		res.Name = strings.TrimSpace(parts[0])
		res.Email = strings.TrimSuffix(parts[1], ">")
	} else {
		res.Name = s
	}
	return res
}

// FindAndUpdateContributor MUST return nil when no match is found.
// FindAndUpdateContributor searches for and returns the matching and update contributor.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🛠️findandupdatecontributor](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/d/i/FindAndUpdateContributor)
func FindAndUpdateContributor(authorStr string) string {
	parsed := parseGitAuthor(authorStr)
	if parsed.Name == "" && parsed.Email == "" {
		return "unknown"
	}

	contributors, _ := ListContributors()

	var found *Contributor

	if parsed.Email != "" {
		for i := range contributors {
			matches := false
			if strings.EqualFold(contributors[i].Email, parsed.Email) {
				matches = true
			} else {
				for _, e := range contributors[i].Emails {
					if strings.EqualFold(e, parsed.Email) {
						matches = true
						break
					}
				}
			}
			if matches {
				found = &contributors[i]

				nameExists := strings.EqualFold(found.Name, parsed.Name)
				if !nameExists && parsed.Name != "" {
					for _, n := range found.Names {
						if strings.EqualFold(n, parsed.Name) {
							nameExists = true
							break
						}
					}
				}
				if !nameExists && parsed.Name != "" {
					found.Names = append(found.Names, parsed.Name)
					SaveContributor(*found)
				}
				break
			}
		}
	}

	if found == nil && parsed.Name != "" {
		for i := range contributors {
			matches := false
			if strings.EqualFold(contributors[i].Name, parsed.Name) {
				matches = true
			} else {
				for _, n := range contributors[i].Names {
					if strings.EqualFold(n, parsed.Name) {
						matches = true
						break
					}
				}
			}
			if matches {
				found = &contributors[i]

				emailExists := strings.EqualFold(found.Email, parsed.Email)
				if !emailExists && parsed.Email != "" {
					for _, e := range found.Emails {
						if strings.EqualFold(e, parsed.Email) {
							emailExists = true
							break
						}
					}
				}
				if !emailExists && parsed.Email != "" {
					found.Emails = append(found.Emails, parsed.Email)
					SaveContributor(*found)
				}
				break
			}
		}
	}

	if found != nil {
		return found.Alias
	}

	return authorStr
}

