// MarshalJSON converts internal filesystem paths to repo emoji IDs for Goal serialization.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🛠️marshaljson](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/d/i/MarshalJSON)
// MarshalJSON MUST perform the MarshalJSON operation.
func (g Goal) MarshalJSON() ([]byte, error) {
	type GoalAlias Goal
	alias := GoalAlias(g)

	if alias.Parent != "" && !strings.Contains(alias.Parent, emojiText(EmojiGoal)) {
		alias.Parent = goalPathToComposeID(alias.Parent)
	}
	return json.Marshal(alias)
}

