func (g *Goal) IsNode() {}

// GetID MUST return the stored value without modification.
// GetID returns the i d of the Goal.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🛠️getid](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/d/i/GetID)
func (g *Goal) GetID() string { return goalArtifactID(g.ID) }

// GetURI MUST return the stored value without modification.
// GetURI returns the u r i of the Goal.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🛠️geturi](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/d/i/GetURI)
func (g *Goal) GetURI() string {
	parts := strings.Split(g.ID, "/")
	result := "repo://"
	for i, p := range parts {
		if i == 0 {
			result += "g/" + PathToUriPath(p)
		} else {
			result += "/g/" + PathToUriPath(p)
		}
	}
	return result
}

