func init() {
	wd, err := os.Getwd()
	if err != nil {
		rootDir = "."
	} else {
		rootDir = findRepoRoot(wd)
	}
	SetRootDir(rootDir)
	var e error
	executor, e = NewExecutorWithContext(rootDir, NewRepoContext(rootDir))
	if e != nil {
		fmt.Fprintf(os.Stderr, "Warning: Failed to initialize GraphQL executor: %v\n", e)
		executor = nil
	}
}

