// Flat MUST preserve only alphanumeric characters and emojis, then lower case.
// [🧰repo⌨️cli💻maingo🔖types🔖utils🛠️flat](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/Flat)
func Flat(text string) string {
	var buf strings.Builder
	for _, r := range text {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r > 0x7F {
			buf.WriteRune(r)
		}
	}
	return strings.ToLower(buf.String())
}

// Slugify MUST complete the operation and return consistent results.
// Slugify performs the slugify operation.
// [🧰repo⌨️cli💻maingo🔖types🔖utils🛠️slugify](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/Slugify)
func Slugify(text string) string {
	runes := []rune(text)
	var buf strings.Builder
	for i, r := range runes {
		if i > 0 && r >= 'A' && r <= 'Z' {
			prev := runes[i-1]
			if prev >= 'a' && prev <= 'z' {
				buf.WriteRune('-')
			} else if prev >= 'A' && prev <= 'Z' && i+1 < len(runes) && runes[i+1] >= 'a' && runes[i+1] <= 'z' {
				buf.WriteRune('-')
			}
		}
		buf.WriteRune(r)
	}
	re := regexp.MustCompile(`[^A-Z0-9]+`)
	slug := re.ReplaceAllString(strings.ToUpper(buf.String()), "-")
	return strings.Trim(slug, "-")
}

