func (ctx *PolicyContext) FilterIgnored(breachs []Breach) []Breach {
	var result []Breach
	for _, v := range breachs {
		file := extractFileFromScope(v.Scope)
		if !ctx.IsIgnored(file, v.Line, v.Kind) {
			result = append(result, v)
		}
	}
	return result
