func (ctx *PolicyContext) DefinitionDocLines(filePath string) map[int]bool {
	if ctx.definitionDocCache == nil {
		ctx.definitionDocCache = make(map[string]map[int]bool)
	}
	if cached, ok := ctx.definitionDocCache[filePath]; ok {
