// Ticket file input normalization for close operations.
// Requirements: Accept repo-relative paths, absolute paths, composerepo file URIs, and file artifact IDs.
// Docs: Used by ticket close to map file identifiers to repo paths.

func normalizeTicketFileInput(filePath string) string {
	normalized := strings.TrimSpace(filePath)
	if normalized == "" {
		return ""
	}
	if strings.HasPrefix(normalized, "composerepo://") && strings.Contains(normalized, "/f/") {
		uri := strings.TrimPrefix(normalized, "composerepo://")
		path := extractPathFromFileUri(uri)
		if path != "" {
			return normalizeRepoPath(path)
		}
	}
	if strings.HasPrefix(normalized, "file://") {
		path := strings.TrimPrefix(normalized, "file://")
		return normalizeRepoPath(path)
	}
	uri := IdToUri(normalized)
	if uri != "" && strings.HasPrefix(uri, "composerepo://") && strings.Contains(uri, "/f/") {
		uriPath := strings.TrimPrefix(uri, "composerepo://")
		path := extractPathFromFileUri(uriPath)
		if path != "" {
			return normalizeRepoPath(path)
		}
	}
	ctx := NewCodebaseContext()
	ctx.LoadBundles()
	if err := ctx.LoadFiles(); err == nil {
		for _, file := range ctx.Files {
			if FileHeaderId(file) == normalized {
				return normalizeRepoPath(file)
			}
		}
	}
	return normalizeRepoPath(normalized)
}

func normalizeTicketFileInputs(files []string) []string {
	if len(files) == 0 {
		return files
	}
	filtered := make([]string, 0, len(files))
	seen := make(map[string]struct{}, len(files))
	for _, filePath := range files {
		normalized := normalizeTicketFileInput(filePath)
		if normalized == "" {
			continue
		}
		if _, ok := seen[normalized]; ok {
			continue
		}
		seen[normalized] = struct{}{}
		filtered = append(filtered, normalized)
	}
	return filtered
}

