// ListTickets MUST return all available tickets entries.
// ListTickets returns a list of tickets entries.
// [🧰composerepo⌨️cli💻maingo🔖types🔖tickets🛠️listtickets](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/ListTickets)
func ListTickets(year, month, day *int) ([]Ticket, error) {
	ticketsDir := GetTicketsDir()
	if !FileExists(ticketsDir) {
		return nil, nil
	}
	var tickets []Ticket
	var years []string
	if year != nil {
		years = []string{PadNumber(*year, 2)}
	} else {
		entries, err := os.ReadDir(ticketsDir)
		if err != nil {
			return nil, err
		}
		for _, e := range entries {
			if e.IsDir() {
				years = append(years, e.Name())
			}
		}
	}
	for _, y := range years {
		yearPath := filepath.Join(ticketsDir, y)
		if !FileExists(yearPath) {
			continue
		}
		var months []string
		if month != nil {
			months = []string{PadNumber(*month, 2)}
		} else {
			entries, err := os.ReadDir(yearPath)
			if err != nil {
				continue
			}
			for _, e := range entries {
				if e.IsDir() {
					months = append(months, e.Name())
				}
			}
		}
		for _, m := range months {
			monthPath := filepath.Join(yearPath, m)
			if !FileExists(monthPath) {
				continue
			}
			var days []string
			if day != nil {
				days = []string{PadNumber(*day, 2)}
			} else {
				entries, err := os.ReadDir(monthPath)
				if err != nil {
					continue
				}
				for _, e := range entries {
					if e.IsDir() {
						days = append(days, e.Name())
					}
				}
			}
			for _, d := range days {
				dayPath := filepath.Join(monthPath, d)
				if !FileExists(dayPath) {
					continue
				}
				yearInt, _ := strconv.Atoi(y)
				monthInt, _ := strconv.Atoi(m)
				dayInt, _ := strconv.Atoi(d)
				filepath.WalkDir(dayPath, func(path string, dEntry fs.DirEntry, err error) error {
					if err != nil {
						return nil
					}
					if !dEntry.IsDir() {
						return nil
					}
					name := dEntry.Name()
					if strings.HasPrefix(name, ".") || name == "node_modules" || name == "dist" || name == "build" || name == "target" || name == "__pycache__" {
						return filepath.SkipDir
					}
					if path == dayPath {
						return nil
					}
					ticketFilePath := filepath.Join(path, "ticket.json")
					if !FileExists(ticketFilePath) {
						return nil
					}
					rel, relErr := filepath.Rel(dayPath, path)
					if relErr != nil {
						return filepath.SkipDir
					}
					slug := filepath.ToSlash(rel)
					ticket, readErr := ReadTicket(yearInt, monthInt, dayInt, slug)
					if readErr == nil {
						tickets = append(tickets, *ticket)
					}
					return filepath.SkipDir
				})
			}
		}
	}
	return tickets, nil
}

