			if err != nil {
				continue
			}
			events = append(events, Event{Kind: KindResult, Command: "technology tree", Data: data})
		}
		sort.Slice(events, func(i, j int) bool {
			return formatMarkdownResult(events[i].Command, events[i].Data) < formatMarkdownResult(events[j].Command, events[j].Data)
		})
		for _, ev := range events {
			stream <- ev
		}
		stream <- Event{Kind: KindDone, Done: &DonePayload{ExitCode: 0, Status: "ok"}}
	}()

	return renderStream(cmd, &config, stream)
}

// StreamOptions holds the data fields for a stream options record.
// [🧰composerepo⌨️cli💻maingo🔖types🔖tickets✂️streamoptions](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/StreamOptions)
type StreamOptions struct {
	ShowIgnored    bool
	ShowGenerated  bool
	ExcludeKinds   []string
	IncludeKinds   []string
	Filter         string
	Query          string
	Regex          bool
	MatchCase      bool
	MatchWholeWord bool

