			number := parts[len(parts)-1]
			if err := c.managementProvider.DeleteIssue(number); err != nil {
				return false, err
			}
		}
	}

	if err := os.RemoveAll(filepath.Dir(path)); err != nil {
		return false, err
	}
	return true, nil
