func (e *Executor) ValidateQuery(query string) error {
	_, err := parser.Parse(parser.ParseParams{
		Source: query,
		Options: parser.ParseOptions{
			NoLocation: true,
		},
	})
	return err
}

// GetOperationType MUST retrieve the requested value or return an error.
// GetOperationType retrieves and returns the operation type.
// [🧰composerepo⌨️cli💻maingo🔖types🔖graphqlexecutor🛠️getoperationtype](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/GraphQL%20Executor/d/i/GetOperationType)
func (e *Executor) GetOperationType(query string) (string, error) {
	doc, err := parser.Parse(parser.ParseParams{
		Source: query,
		Options: parser.ParseOptions{
			NoLocation: true,
		},
	})
	if err != nil {
		return "", err
	}
	for _, def := range doc.Definitions {
		if opDef, ok := def.(*ast.OperationDefinition); ok {
			return string(opDef.Operation), nil
		}
	}
	return "query", nil
}

