						return ticket.Goal, nil
					},
				},
				"parent": &graphql.Field{
					Type: graphql.String,
					Resolve: func(p graphql.ResolveParams) (interface{}, error) {
						ticket := p.Source.(*Ticket)
						if ticket.Parent == "" {
							return nil, nil
						}
						return ticket.Parent, nil
					},
				},
