func (r *repoResolver) Tickets(ctx context.Context, obj *Repo, year *int, month *int, day *int, status *TicketStatus, filter *FilterInput) ([]*Ticket, error) {
	if r.Ctx != nil {
		opts := filter.ToStreamOptions()
		ticketChan := make(chan Ticket)
		go StreamTickets(ctx, year, month, day, ticketChan, opts)
		var tickets []*Ticket
		for t := range ticketChan {
			tCopy := t
			if status != nil && tCopy.Status != *status {
				continue
			}
			tickets = append(tickets, &tCopy)
		}
		return tickets, nil
	}
	return []*Ticket{}, nil
}

// Policies MUST return a non-nil error when the operation fails.
// Policies performs the policies operation on the repo resolver.
// [🧰composerepo⌨️cli💻maingo🔖types🔖entityresolvers🛠️policies](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Entity%20Resolvers/d/i/Policies)
func (r *repoResolver) Policies(ctx context.Context, obj *Repo, filter *FilterInput) ([]*Policy, error) {
	if r.Ctx != nil {
		opts := filter.ToStreamOptions()
		policyChan := make(chan PolicyDef)
		go StreamPolicies(ctx, policyChan, opts)
		var policies []*Policy
		for p := range policyChan {
			desc := p.Description
			var vks []*StatuteMeta
			for _, k := range p.AllKinds() {
				meta := k.Info()
				meta.PolicyID = p.ID
				vks = append(vks, &meta)
			}
			policies = append(policies, &Policy{
				ID:          p.ID,
				Name:        p.Name,
				Description: &desc,
				Scopes:      p.Scopes,
				Groups:      p.Groups,
				Statutes:    vks,
			})
		}
		return policies, nil
	}
	return []*Policy{}, nil
}

