// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks✂️blockedtoolpatterns](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/BlockedToolPatterns)
var BlockedToolPatterns = []string{
	"git checkout",
	"git stash",
	"git stash pop",
	"git stash drop",
	"git stash apply",
	"git reset --hard",
	"git clean -fd",
