// shellSegmentRE splits a command string by common shell operators.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks✂️shellsegmentre](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/shellSegmentRE)
var shellSegmentRE = regexp.MustCompile(`&&|\|\||;|\|`)

// shellSequenceRE splits a command string by sequence operators (&&, ||, ;) but NOT pipe (|).
// This is used for command classification where pipe chains should be treated as a single command.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks✂️shellsequencere](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/shellSequenceRE)
var shellSequenceRE = regexp.MustCompile(`&&|\|\||;`)
var grepLineWithPathRE = regexp.MustCompile(`^([^:]+):([0-9]+)([:\-].*)?$`)
var grepContextWithPathRE = regexp.MustCompile(`^(.+?)-([0-9]+)-`)
var grepLineOnlyRE = regexp.MustCompile(`^([0-9]+)([:\-].*)?$`)

// splitCommandSegments splits a shell command string by operators (&&, ||, ;, |) into individual segments.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks✂️splitcommandsegments](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/splitCommandSegments)
func splitCommandSegments(cmd string) []string {
	var segments []string
	for _, part := range shellSegmentRE.Split(cmd, -1) {
		part = strings.TrimSpace(part)
		if part != "" {
			segments = append(segments, part)
		}
	}
	return segments
}

// isCommandSegmentBlocked checks whether a single command segment starts with a blocked pattern.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks✂️iscommandsegmentblocked](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/isCommandSegmentBlocked)
func isCommandSegmentBlocked(segment string) (bool, string) {
	segment = strings.TrimSpace(segment)
	if segment == "" {
		return false, ""
	}
	lower := strings.ToLower(segment)
	for _, pattern := range BlockedToolPatterns {
		patternLower := strings.ToLower(pattern)
		if strings.HasPrefix(lower, patternLower) {
			rest := lower[len(patternLower):]
			if rest == "" || rest[0] == ' ' || rest[0] == '\t' {
				return true, fmt.Sprintf("blocked: %q matches denied pattern %q", segment, pattern)
			}
		}
	}
	return false, ""
}

// IsToolBlocked checks whether a tool invocation matches a blocked pattern.
// Uses segment-start matching: only blocks if a command segment STARTS WITH a blocked pattern,
// preventing false positives from grep/echo commands that mention blocked patterns in arguments.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks🛠️istoolblocked](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Hooks/d/i/IsToolBlocked)
// IsToolBlocked MUST perform the IsToolBlocked operation.
func IsToolBlocked(toolName string, toolArgs string) (bool, string) {
	for _, segment := range splitCommandSegments(toolArgs) {
		if blocked, reason := isCommandSegmentBlocked(segment); blocked {
			return blocked, reason
		}
	}
	for _, segment := range splitCommandSegments(toolName) {
		if blocked, reason := isCommandSegmentBlocked(segment); blocked {
			return blocked, reason
		}
	}
	return false, ""
}

// extractCommandFromStdin parses native client JSON from stdin and extracts the command string for blocking checks.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks✂️extractcommandfromstdin](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/extractCommandFromStdin)
func extractCommandFromStdin(input json.RawMessage) string {
	if len(input) == 0 {
		return ""
	}
	var data map[string]interface{}
	if err := json.Unmarshal(input, &data); err != nil {
		return ""
	}
	if toolInput, ok := data["tool_input"]; ok {
		if m, ok := toolInput.(map[string]interface{}); ok {
			if cmd, ok := m["command"].(string); ok {
				return cmd
			}
		}
	}
	if cmd, ok := data["command"].(string); ok {
		return cmd
	}
	if toolInfo, ok := data["tool_info"]; ok {
		if m, ok := toolInfo.(map[string]interface{}); ok {
			if cmd, ok := m["command_line"].(string); ok {
				return cmd
			}
		}
	}
	if inputData, ok := data["input"].(map[string]interface{}); ok {
		if toolInfo, ok := inputData["tool_info"].(map[string]interface{}); ok {
			if cmd, ok := toolInfo["command_line"].(string); ok {
				return cmd
			}
		}
		if cmd, ok := inputData["command_line"].(string); ok {
			return cmd
		}
		if cmd, ok := inputData["command"].(string); ok {
			return cmd
		}
	}
	if eventData, ok := data["event"].(map[string]interface{}); ok {
		if eventInput, ok := eventData["input"].(map[string]interface{}); ok {
			if cmd, ok := eventInput["command"].(string); ok {
				return cmd
			}
		}
	}
	return ""
}

// extractToolNameFromStdin parses native client JSON from stdin and extracts the tool_name field.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks✂️extracttoolnamefromstdin](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/extractToolNameFromStdin)
func extractToolNameFromStdin(input json.RawMessage) string {
	if len(input) == 0 {
		return ""
	}
	var data map[string]interface{}
	if err := json.Unmarshal(input, &data); err != nil {
		return ""
	}

	if nativeData, ok := data["native"].(map[string]interface{}); ok {
		if eventData, ok := nativeData["event"].(map[string]interface{}); ok {
			if tn, ok := eventData["tool_name"].(string); ok {
				return tn
			}
		}
	}

	if eventData, ok := data["event"].(map[string]interface{}); ok {
		if tn, ok := eventData["tool_name"].(string); ok {
			return tn
		}
		if tn, ok := eventData["name"].(string); ok {
			return tn
		}
	}

	if tn, ok := data["tool_name"].(string); ok {
		return tn
	}

	if inputData, ok := data["input"].(map[string]interface{}); ok {
		var cmd string
		if toolInfo, ok := inputData["tool_info"].(map[string]interface{}); ok {
			if c, ok := toolInfo["command_line"].(string); ok {
				cmd = c
			}
		}
		if cmd == "" {
			if c, ok := inputData["command_line"].(string); ok {
				cmd = c
			}
		}
		if cmd == "" {
			if c, ok := inputData["command"].(string); ok {
				cmd = c
			}
		}
		if cmd != "" {
			parts := strings.Fields(cmd)
			if len(parts) > 0 {
				toolName := parts[0]
				switch toolName {
				case "grep", "rg":
					return "grep_search"
				case "find", "fd":
					return "file_search"
				case "awk", "gawk", "mawk", "nawk":
					return "read_file"
				case "sed":
					for _, arg := range parts[1:] {
						if strings.HasPrefix(arg, "--") {
							if arg == "--in-place" {
								return "replace_string_in_file"
							}
						} else if strings.HasPrefix(arg, "-") && strings.ContainsRune(arg, 'i') {
							return "replace_string_in_file"
						}
					}
					return "read_file"
				case "cat", "bat", "less", "more":
					return "read_file"
				case "ls", "exa", "eza", "tree":
					return "list_dir"
				case "mkdir", "rmdir":
					return "create_directory"
				case "touch":
					return "create_file"
				case "rm", "mv", "cp":
					return "editfiles"
				}
			}
		}
	}
	return ""
}

