// formatVSCodeHookOutput produces VS Code-compatible JSON output for hook results.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks✂️formatvscodehookoutput](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/formatVSCodeHookOutput)
func formatVSCodeHookOutput(hookEventName string, result HookResult) string {
	output := map[string]interface{}{}
	allowed := result.IsAllowed()
	message := result.GetMessage()
	switch hookEventName {
	case "PreToolUse":
		if !allowed {
			output["hookSpecificOutput"] = map[string]interface{}{
				"hookEventName":            "PreToolUse",
				"permissionDecision":       "deny",
				"permissionDecisionReason": message,
			}
		} else {
			output["hookSpecificOutput"] = map[string]interface{}{
				"hookEventName":      "PreToolUse",
				"permissionDecision": "allow",
			}
		}
	case "PostToolUse":
		hso := map[string]interface{}{"hookEventName": "PostToolUse"}
		if message != "" {
			hso["additionalContext"] = message
		}
		output["hookSpecificOutput"] = hso
	case "SessionStart":
		hso := map[string]interface{}{"hookEventName": "SessionStart"}
		if message != "" {
			hso["additionalContext"] = message
		}
		output["hookSpecificOutput"] = hso
	case "SubagentStart":
		hso := map[string]interface{}{"hookEventName": "SubagentStart"}
		if message != "" {
			hso["additionalContext"] = message
		}
		output["hookSpecificOutput"] = hso
	case "UserPromptSubmit":
		hso := map[string]interface{}{"hookEventName": "UserPromptSubmit"}
		if message != "" {
			hso["additionalContext"] = message
		}
		output["hookSpecificOutput"] = hso
	case "Stop":
		hso := map[string]interface{}{"hookEventName": "Stop"}
		if message != "" {
			hso["additionalContext"] = message
		}
		output["hookSpecificOutput"] = hso
	case "SubagentStop":
		hso := map[string]interface{}{"hookEventName": "SubagentStop"}
		if message != "" {
			hso["additionalContext"] = message
		}
		output["hookSpecificOutput"] = hso
	case "PreCompact":
		hso := map[string]interface{}{"hookEventName": "PreCompact"}
		if message != "" {
			hso["additionalContext"] = message
		}
		output["hookSpecificOutput"] = hso
	}
	out, _ := json.Marshal(output)
	return string(out)
}

// extractCheckpointIDFromResult extracts the checkpoint/checkpoint ID from a hook result.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks✂️extractcheckpointidfromresult](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/extractCheckpointIDFromResult)
func extractCheckpointIDFromResult(result HookResult, repoRoot string) string {
	switch r := result.(type) {
	case HookResultVersionCheckpointEnded:
		if r.Checkpoint != "" {
			return r.Checkpoint
		}
	case HookResultVersionCheckinStarting:
		if r.Checkpoint != "" {
			return r.Checkpoint
		}
	case HookResultVersionCheckinEnded:
		if r.Checkpoint != "" {
			return r.Checkpoint
		}
	case HookResultVersionCheckoutEnded:
		if r.Checkpoint != "" {
			return r.Checkpoint
		}
	}
	vcp := DefaultVersionControlProvider()
	if sha, err := vcp.CurrentCheckpoint(repoRoot); err == nil && sha != "" {
		return sha
	}
	return "unknown"
}

// resolvePathToFileID converts a raw file path (absolute or relative) to a repo file ID.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks🛠️resolvepathtofiled](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/resolvePathToFileID)
func resolvePathToFileID(path string) string {
	if path == "" {
		return ""
	}
	normalized := normalizeHookPath(path)
	if normalized == "" {
		return ""
	}
	return buildFileID(normalized, nil)
}

// resolveRangeRef converts a "path#Lstart-Lend" or "path#Lstart" reference to a repo range/line ID.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks🛠️resolverangeref](composerepo://definition/repo/cli/main.go/Types/Cli/Hooks/resolveRangeRef)
func resolveRangeRef(ref string) string {
	if ref == "" {
		return ""
	}
	hashIdx := strings.Index(ref, "#L")
	if hashIdx < 0 {

		return resolvePathToFileID(ref)
	}
	filePath := ref[:hashIdx]
	lineRef := ref[hashIdx+2:]
	fileID := resolvePathToFileID(filePath)
	if fileID == "" {
		return ref
	}

	dashIdx := strings.Index(lineRef, "-L")
	if dashIdx >= 0 {
		startStr := lineRef[:dashIdx]
		endStr := lineRef[dashIdx+2:]
		return fileID + "📌" + startStr + "📌" + endStr
	}
	return fileID + "📌" + lineRef
}

func resolveEventCheckpointID(value string) string {
	trimmed := strings.TrimSpace(value)
	if trimmed == "" {
		return ""
	}
	if strings.HasPrefix(trimmed, "checkpoint:") {
		trimmed = strings.TrimPrefix(trimmed, "checkpoint:")
	}
	if strings.Contains(trimmed, emojiText(EmojiCheckpoint)) {
		return trimmed
	}
	return GetArtifactID("checkpoint", map[string]interface{}{"sha": trimmed})
}

func resolveEventSessionID(value string) string {
	trimmed := strings.TrimSpace(value)
	if trimmed == "" {
		return ""
	}
	return normalizeTicketSessionID(trimmed)
}

func resolveEventSecondID(value string) string {
	trimmed := strings.TrimSpace(value)
	if trimmed == "" {
		return ""
	}
	if strings.Contains(trimmed, emojiText(EmojiYear)) && strings.Contains(trimmed, emojiText(EmojiSecond)) {
		return trimmed
	}
	parsed, err := time.Parse(time.RFC3339Nano, trimmed)
	if err != nil {
		return trimmed
	}
	return FormatSecond(parsed.UTC())
}

