// writeSessionMeta MUST persist session metadata without overwriting existing data.
// writeSessionMeta writes a minimal session.json file for the given session directory.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks🛠️writesessionmeta](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Hooks/d/i/WriteSessionMeta)
func writeSessionMeta(dir, sessionID string, meta SessionMeta) {
	if sessionID == "" || dir == "" {
		return
	}
	path := filepath.Join(dir, "session.json")
	if _, err := os.Stat(path); err == nil {
		return
	}
	data, err := json.MarshalIndent(meta, "", "  ")
	if err != nil {
		return
	}
	f, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0644)
	if err != nil {
		return
	}
	defer f.Close()
	_, _ = f.Write(data)
}

