// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks🛠️updatesessionmetaplan](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Hooks/d/i/updateSessionMetaPlan)
func updateSessionMetaPlan(dir string, steps []HookPlanStep, second string) {
	if dir == "" || len(steps) == 0 {
