// RunHook executes the hook logic for the given context and logs the invocation.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖hooks🛠️runhook](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Hooks/d/i/RunHook)
// RunHook MUST perform the RunHook operation.
func RunHook(hctx HookContext) HookResult {
	if hctx.RepoRoot != "" {
		SetRootDir(hctx.RepoRoot)
	}
	result := dispatchHook(hctx)
	logHook(hctx, result)
	trackHookInOpenTicket(hctx, result)
	if hctx.Event == HookVersionCheckpointEnded {
		checkpointID := extractCheckpointIDFromResult(result, hctx.RepoRoot)
		if checkpointID != "" {
			storeCheckpointDiff(hctx.RepoRoot, checkpointID)
		}
	}
	return result
}

func latestOpenTicket() (*Ticket, error) {
	tickets, err := ListTickets(nil, nil, nil)
	if err != nil {
		return nil, err
	}
	var latest *Ticket
	for i := range tickets {
		if tickets[i].Status != TicketStatusOpen {
			continue
		}
		if latest == nil {
			copyTicket := tickets[i]
			latest = &copyTicket
			continue
		}
		if tickets[i].GetDateStarted().After(latest.GetDateStarted()) {
			copyTicket := tickets[i]
			latest = &copyTicket
		}
	}
	if latest == nil {
		return nil, nil
	}
	return latest, nil
}

func appendUniqueString(values []string, value string) []string {
	value = strings.TrimSpace(value)
	if value == "" {
		return values
	}
	for _, current := range values {
		if current == value {
			return values
		}
	}
	return append(values, value)
}

var (
	runtimeTicketSessionIDOnce sync.Once
	runtimeTicketSessionID     string
	testSessionIDOverride      string // overrides currentTicketSessionID in tests only
)

func normalizeTicketSessionID(value string) string {
	normalized := strings.TrimSpace(value)
	if normalized == "" {
		return ""
	}
	// If the value contains a checkpoint emoji, it is already in the new format: <checkpointID>⚪<uuid>.
	// Preserve the checkpoint prefix and only flatten the uuid part.
	checkpointEmoji := emojiText(EmojiCheckpoint)
	sessionEmoji := emojiText(EmojiSession)
	if idx := strings.Index(normalized, checkpointEmoji); idx >= 0 {
		sessionIdx := strings.LastIndex(normalized, sessionEmoji)
		if sessionIdx > idx {
			checkpointPart := normalized[:sessionIdx]
			uuidPart := normalized[sessionIdx+len(sessionEmoji):]
			uuidFlat := Flat(uuidPart)
			if uuidFlat == "" {
				return ""
			}
			return checkpointPart + sessionEmoji + uuidFlat
		}
	}
	for _, prefix := range []string{
		emojiText(EmojiSessionRunning),
		emojiText(EmojiSessionCompleted),
		emojiText(EmojiSessionInterrupted),
		sessionEmoji,
	} {
		if strings.HasPrefix(normalized, prefix) {
			normalized = strings.TrimPrefix(normalized, prefix)
			break
		}
	}
	normalized = Flat(normalized)
	if normalized == "" {
		return ""
	}
	return sessionEmoji + normalized
}

func appendTicketSessionID(ticket *Ticket, sessionID string) {
	if ticket == nil {
		return
	}
	normalized := normalizeTicketSessionID(sessionID)
	if normalized == "" {
		return
	}
	ticket.Sessions = appendUniqueString(ticket.Sessions, normalized)
}

func currentTicketSessionID() string {
	if testSessionIDOverride != "" {
		return testSessionIDOverride
	}
	runtimeTicketSessionIDOnce.Do(func() {
		var uuid string
		candidates := []string{
			os.Getenv("COMPOSE_SESSION_ID"),
			os.Getenv("COMPOSER_SESSION_ID"),
			os.Getenv("COMPOSER_AGENT_SESSION_ID"),
			os.Getenv("CODEX_THREAD_ID"),
			os.Getenv("COPILOT_CHAT_SESSION_ID"),
			os.Getenv("WINDSURF_SESSION_ID"),
			os.Getenv("CLAUDE_SESSION_ID"),
			os.Getenv("ANTIGRAVITY_SESSION_ID"),
		}
		for _, candidate := range candidates {
			if strings.TrimSpace(candidate) != "" {
				uuid = candidate
				break
			}
		}
		if uuid == "" {
			uuid = fmt.Sprintf("%d-%d", time.Now().UTC().UnixNano(), rand.Int63())
		}
		checkpointPrefix := ""
		vcp := DefaultVersionControlProvider()
		if sha, err := vcp.CurrentCheckpoint(GetRootDir()); err == nil && sha != "" {
			checkpointPrefix = GetArtifactID("checkpoint", map[string]interface{}{"sha": sha})
		}
		runtimeTicketSessionID = checkpointPrefix + emojiText(EmojiSession) + Flat(uuid)
	})
	return runtimeTicketSessionID
}

