// File utility functions for reading, writing and path manipulation.

// MoveFile MUST return a non-nil error when the operation fails.
// MoveFile performs the move file operation.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖fileutilities🛠️movefile](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/File%20Utilities/d/i/MoveFile)
func MoveFile(sourcePath, destPath string) error {
	inputFile, err := os.Open(sourcePath)
	if err != nil {
		return fmt.Errorf("couldn't open source file: %v", err)
	}
	outputFile, err := os.Create(destPath)
	if err != nil {
		inputFile.Close()
		return fmt.Errorf("couldn't open dest file: %v", err)
	}
	defer outputFile.Close()
	_, err = io.Copy(outputFile, inputFile)
	inputFile.Close()
	if err != nil {
		return fmt.Errorf("writing to output file failed: %v", err)
	}

	err = os.Remove(sourcePath)
	if err != nil {
		return fmt.Errorf("failed removing original file: %v", err)
	}
	return nil
}

// CopyFile MUST return a non-nil error when the operation fails.
// CopyFile performs the copy file operation.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖fileutilities🛠️copyfile](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/File%20Utilities/d/i/CopyFile)
func CopyFile(sourcePath, destPath string) error {
	inputFile, err := os.Open(sourcePath)
	if err != nil {
		return fmt.Errorf("couldn't open source file: %v", err)
	}
	defer inputFile.Close()
	outputFile, err := os.Create(destPath)
	if err != nil {
		return fmt.Errorf("couldn't open dest file: %v", err)
	}
	defer outputFile.Close()
	_, err = io.Copy(outputFile, inputFile)
	if err != nil {
		return fmt.Errorf("writing to output file failed: %v", err)
	}
	return nil
}

