		if err != nil {
			return err
		}
		if !d.IsDir() && d.Name() == "goal.json" {
			content, err := ReadTextFile(path)
			if err != nil {
				return err
			}
			var goal Goal
			if err := json.Unmarshal([]byte(content), &goal); err != nil {
				return err
			}
			relPath, _ := filepath.Rel(dir, path)
			idPath := filepath.Dir(relPath)
			goal.ID = filepath.ToSlash(idPath)

			if idx := strings.LastIndex(goal.ID, "/"); idx != -1 {
				goal.Parent = goal.ID[:idx]
			} else {
				goal.Parent = ""
			}
			goal.Path = path
			goals = append(goals, &goal)
		}
		return nil
	})
	return goals, err
}

// ReadGoal MUST return the goal content or an error if unavailable.
// ReadGoal reads and returns goal from the source.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖goals🛠️readgoal](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Goals/d/i/ReadGoal)
func ReadGoal(id string) (*Goal, error) {
	dir := GetRepoGoalsDir()
	path := filepath.Join(dir, filepath.FromSlash(id), "goal.json")
	if !FileExists(path) {
		return nil, fmt.Errorf("goal file not found: %s", path)
	}
	content, err := ReadTextFile(path)
	if err != nil {
		return nil, err
	}
	var goal Goal
	if err := json.Unmarshal([]byte(content), &goal); err != nil {
		return nil, err
	}
	goal.ID = id
	goal.Path = path

	if idx := strings.LastIndex(id, "/"); idx != -1 {
		goal.Parent = id[:idx]
	} else {
		goal.Parent = ""
	}
	return &goal, nil
}

// StreamGoals MUST invoke the callback for each matching goals entry.
// StreamGoals streams goals entries through the callback.
// [🧰composerepo⌨️cli💻maingo🔖types🔖cli🔖goals🛠️streamgoals](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Goals/d/i/StreamGoals)
func StreamGoals(ctx context.Context, out chan<- *Goal, opts ...StreamOptions) error {
	defer close(out)
	var options StreamOptions
	if len(opts) > 0 {
		options = opts[0]
	}

	goals, err := ListGoals()
	if err != nil {
		return err
	}

	for _, g := range goals {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
			if !matchesFilter(g.ID, options) && !matchesFilter(g.Title, options) {
				continue
			}
			if !matchesQuery(g.ID+" "+g.Title+" "+g.Description+" "+g.Status, options) {
				continue
			}
			out <- g
		}
	}
	return nil
}

