// Artifact ID parsing and resolution utilities.

// SemanticId holds the data fields for a semantic id record.
// [🧰composerepo⌨️cli💻maingo🔖types🔖todos🔖entityrendering🔖artifactid✂️semanticid](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/SemanticId)
type SemanticId struct {
	Emoji string
	Value string
}

func emojiText(emoji string) string {
	stripped := strings.ReplaceAll(emoji, "\uFE0E", "")
	textDefaultEmojis := []string{
		"\U0001F3D7", "\u2328", "\U0001F5B1", "\U0001F5C3",
		"\u2699", "\u2696", "\U0001F3F7", "\U0001F6E0",
		"\u2702", "\U0001F6E1", "\U0001F5D1",
		"\u2600", "\u23F1", "\u270F", "\U0001F46E",
	}
	base := strings.ReplaceAll(stripped, "\uFE0F", "")
	for _, td := range textDefaultEmojis {
		if strings.Contains(base, td) {
			return strings.ReplaceAll(base, td, td+"\uFE0F")
		}
	}
	return base
}

// String MUST return a non-empty string representation.
// String returns the string representation of the semantic id.
// [🧰composerepo⌨️cli💻maingo🔖types🔖todos🔖entityrendering🔖artifactid🛠️string](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/String)
func (s SemanticId) String() string {
	if s.Value == "" {
		return emojiText(s.Emoji)
	}
	return fmt.Sprintf("%s%s", emojiText(s.Emoji), s.Value)
}

func technologyKindEmoji(data map[string]interface{}) string {
	if val, ok := data["kind"].(string); ok {
		switch val {
		case "infrastructure":
			return emojiText(EmojiTechnologyInfra)
		case "research":
			return emojiText(EmojiTechnologyResearch)
		case "mono":
			return emojiText(EmojiTechnologyMono)
		case "user":
