func containsUriSection(uri string) bool {
	if strings.HasPrefix(uri, "composerepo://section/") {
		return true
	}

	// so require /s/ without a subsequent /d/ to match only section URIs
	return strings.Contains(uri, "/s/") && !strings.Contains(uri, "/d/")
}

func containsUriDefinition(uri string) bool {
	return strings.Contains(uri, "/d/") || strings.HasPrefix(uri, "composerepo://definition/")
}

func extractFileAndSectionsFromUri(uri string) (filePath string, sectionSlugs []string) {
	p := strings.TrimPrefix(uri, "composerepo://")
	var sectionParts []string
	remaining := p
	for {
		idx := strings.Index(remaining, "/s/")
		if idx < 0 {
			break
		}
		before := remaining[:idx]
		after := remaining[idx+3:]
		if len(sectionParts) == 0 {
			_ = before
		}
		nextS := strings.Index(after, "/s/")
		nextD := strings.Index(after, "/d/")
		endIdx := len(after)
		if nextS >= 0 && nextS < endIdx {
			endIdx = nextS
		}
		if nextD >= 0 && nextD < endIdx {
			endIdx = nextD
		}
		sectionParts = append(sectionParts, PathFromUriPath(after[:endIdx]))
		remaining = after[endIdx:]
	}
	fIdx := strings.Index(p, "/f/")
	if fIdx >= 0 {
		rest := p[fIdx+3:]
		nextSlash := strings.Index(rest, "/")
		if nextSlash < 0 {
			filePath = PathFromUriPath(rest)
		} else {
			filePath = PathFromUriPath(rest[:nextSlash])
		}
	}
	return filePath, sectionParts
}

func extractFileAndDefinitionFromUri(uri string) (filePath string, defName string) {
	p := strings.TrimPrefix(uri, "composerepo://")
	fIdx := strings.Index(p, "/f/")
	if fIdx >= 0 {
		rest := p[fIdx+3:]
		nextSlash := strings.Index(rest, "/")
		if nextSlash < 0 {
			filePath = PathFromUriPath(rest)
		} else {
			filePath = PathFromUriPath(rest[:nextSlash])
		}
	}
	dIdx := strings.LastIndex(p, "/d/")
	if dIdx >= 0 {
		rest := p[dIdx+3:]
		dParts := strings.SplitN(rest, "/", 2)
		if len(dParts) >= 2 {
			defName = PathFromUriPath(dParts[1])
		}
	}
	return filePath, defName
}

// ArtifactRef holds the data fields for a artifact ref record.
// [🧰composerepo⌨️cli💻maingo🔖types🔖todos🔖entityrendering🔖artifactid✂️artifactref](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/ArtifactRef)
type ArtifactRef struct {
	Kind         string
	Path         string
	SectionParts []string
}

// ParseArtifactRef MUST return the parsed result or an error for invalid input.
// ParseArtifactRef parses and returns the artifact ref from the input.
// [🧰composerepo⌨️cli💻maingo🔖types🔖todos🔖entityrendering🔖artifactid🛠️parseartifactref](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/ParseArtifactRef)
func ParseArtifactRef(ref string) ArtifactRef {
	clean := strings.ReplaceAll(ref, "\uFE0E", "")
	clean = strings.ReplaceAll(clean, "\uFE0F", "")
	if uri := IdToUri(clean); uri != "" && strings.HasPrefix(uri, "composerepo://") {
		if containsUriSection(uri) && !containsUriDefinition(uri) {
			filePath, sectionSlugs := extractFileAndSectionsFromUri(uri)
			return ArtifactRef{Kind: "section", Path: NormalizePath(filePath), SectionParts: sectionSlugs}
		}
		if containsUriDefinition(uri) {
			filePath, defName := extractFileAndDefinitionFromUri(uri)
			if defName != "" {
				return ArtifactRef{Kind: "definition", Path: NormalizePath(filePath + "§" + defName)}
			}
			return ArtifactRef{Kind: "definition", Path: NormalizePath(filePath)}
		}
	}

	sectionEmojis := []string{"🔖"}
	for _, e := range sectionEmojis {
		if strings.HasPrefix(clean, e) {
			rest := clean[len(e):]
			parts := strings.SplitN(rest, "#", 2)
			filePath := NormalizePath(parts[0])
			var sectionParts []string
			if len(parts) > 1 {
				sectionParts = strings.Split(parts[1], "#")
			}
			return ArtifactRef{Kind: "section", Path: filePath, SectionParts: sectionParts}
		}
	}

	defEmojis := []string{"🏷️", "✂️️", "🪨", "🛠️"}
	for _, e := range defEmojis {
		if strings.HasPrefix(clean, e) {
			rest := clean[len(e):]
			return ArtifactRef{Kind: "definition", Path: NormalizePath(rest)}
		}
	}

	folderEmojis := []string{"📁", "🗃️", "📂"}
	for _, e := range folderEmojis {
		if strings.HasPrefix(clean, e) {
			rest := clean[len(e):]
			return ArtifactRef{Kind: "folder", Path: NormalizePath(strings.TrimSuffix(rest, "/"))}
		}
	}

	fileEmojis := []string{"💻", "🥼", "📜", "📃", "⚙️", "💾", "⚖️", "📄"}
	for _, e := range fileEmojis {
		if strings.HasPrefix(clean, e) {
			rest := clean[len(e):]
			return ArtifactRef{Kind: "file", Path: NormalizePath(rest)}
		}
	}

	if strings.Contains(ref, "#") {
		parts := strings.SplitN(ref, "#", 2)
		filePath := NormalizePath(parts[0])
		var sectionParts []string
		if len(parts) > 1 {
			sectionParts = strings.Split(parts[1], "#")
		}
		return ArtifactRef{Kind: "section", Path: filePath, SectionParts: sectionParts}
	}
	if strings.HasSuffix(ref, "/") {
		return ArtifactRef{Kind: "folder", Path: NormalizePath(strings.TrimSuffix(ref, "/"))}
	}
	normalized := NormalizePath(ref)
	absPath := filepath.Join(rootDir, normalized)
	if info, err := os.Stat(absPath); err == nil && info.IsDir() {
		return ArtifactRef{Kind: "folder", Path: normalized}
	}
	return ArtifactRef{Kind: "file", Path: normalized}
}

// UnSlugify MUST complete the operation successfully.
// UnSlugify performs the un slugify operation.
// [🧰composerepo⌨️cli💻maingo🔖types🔖todos🔖entityrendering🔖artifactid🛠️unslugify](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/UnSlugify)
func UnSlugify(slug string) string {
	parts := strings.Split(slug, "-")
	for i, p := range parts {
		if len(p) > 0 {
			parts[i] = strings.ToUpper(p[:1]) + strings.ToLower(p[1:])
		}
	}
	return strings.Join(parts, " ")
}

// FindSectionBySlug MUST return the matching result or an error if not found.
// FindSectionBySlug locates and returns the matching section by slug.
// [🧰composerepo⌨️cli💻maingo🔖types🔖todos🔖entityrendering🔖artifactid🛠️findsectionbyslug](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/FindSectionBySlug)
func FindSectionBySlug(sections []Section, slug string) *Section {
	for i := range sections {
		if Slugify(sections[i].Name) == slug {
			return &sections[i]
		}
		if found := FindSectionBySlug(sections[i].Children, slug); found != nil {
			return found
		}
	}
	return nil
}

// ResolveSectionName MUST return the resolved value or an error if unresolvable.
// ResolveSectionName resolves and returns the section name.
// [🧰composerepo⌨️cli💻maingo🔖types🔖todos🔖entityrendering🔖artifactid🛠️resolvesectionname](composerepo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Todos/s/Entity%20Rendering/s/Artifact%20ID/d/i/ResolveSectionName)
func ResolveSectionName(filePath string, slug string) string {
	absPath := filepath.Join(rootDir, filePath)
	content, err := ReadTextFile(absPath)
	if err != nil {
		return UnSlugify(slug)
	}
	lang := GetLanguage(filePath)
	if lang == nil || !lang.SupportsSections() {
		return UnSlugify(slug)
	}
	sections := lang.ParseSections(content)
	section := FindSectionBySlug(sections, slug)
	if section != nil {
		return section.Name
	}
	return UnSlugify(slug)
}

