		if rest == "" {
			return "composerepo://gs"
		}
		goalEmoji := emojiText(EmojiGoal)
		segments := strings.Split(rest, goalEmoji)
		result := "composerepo://g/" + PathToUriPath(segments[0])
		for _, s := range segments[1:] {
			result += "/g/" + PathToUriPath(s)
		}
		return result
	}
	if rest, ok := hasPrefix(normalized, EmojiDraft); ok {
		if rest == "" {
			return "composerepo://drs"
		}
		return "composerepo://drs/" + rest
	}
	if rest, ok := hasPrefix(normalized, EmojiPolicy); ok {
		if rest == "" {
			return "composerepo://pls"
		}
		return "composerepo://pls/pl/" + rest
	}
	if rest, ok := hasPrefix(normalized, EmojiBreach); ok {
		if rest == "" {
			return "composerepo://brs"
		}
		return "composerepo://brs/" + rest
	}
	if rest, ok := hasPrefix(normalized, EmojiContributor); ok {
		if rest == "" {
			return "composerepo://cs"
		}
		return "composerepo://cs/" + rest
	}
	if rest, ok := hasPrefix(normalized, EmojiCheckpoint); ok {
		if rest == "" {
			return "composerepo://cms"
		}
		return "composerepo://cms/" + rest
	}
	if rest, ok := hasPrefix(normalized, EmojiSession); ok {
		if rest == "" {
			return "composerepo://s"
		}
		return "composerepo://s/" + rest
	}
	return ""
}

